  ?'Par le sens : recherche sémantique en cours. En attendant, pistes PAR LES MOTS uniquement : vérifiez les citations. Aucune pertinence sémantique confirmée.'
  :'Par le sens : aucun classement sémantique confirmé ('+String(reason||'recherche non concluante')+'). Pistes PAR LES MOTS uniquement : vérifiez les citations. Aucune pertinence sémantique confirmée.';

  return true;
}
// R252: a settled search cannot continue displaying an obsolete 'in progress'
// caption. Never rewrite the semantic result, a newer query or another UI panel.
function r252FinalizeProvisionalLexical(raw,generation){
  if(!r150SemanticLive(raw,generation))return false;
  const results=document.getElementById('search-results');
  if(!results)return false;
  const banner=results.querySelector('.search-suggestion-box[data-r252-lexical-generation="'+String(generation)+'"]');
  if(!banner||banner.dataset.r252LexicalStatus!=='provisional')return false;
  banner.dataset.r252LexicalStatus='terminal';
  banner.textContent='Par le sens : la recherche est terminée sans classement sémantique confirmé. Pistes PAR LES MOTS uniquement : vérifiez les citations. Aucune pertinence sémantique confirmée.';

// A timer callback can complete AFTER the semantic function has returned.
// Such a callback must never publish a late provisional banner.
if(!checked.ok||!checked.value||semanticSettled||semanticDone||!r150SemanticLive(raw,generation))return false;
